INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.94.0',
  '2026-09-20',
  'Пульт ТВ: «Фото и видео», альбомы архивом, альбомы музыки с дисками',
  E'Раздел «Фото» теперь называется «Фото и видео»: в альбомах давно живут не только снимки, но и ролики с телефона.\n\nАрхивом из админки можно загрузить не только альбом музыки, но и альбом фото и видео: папка внутри архива станет альбомом, подпапки («День 1», «День 2») сохранятся, лишние файлы не распакуются.\n\nАльбом музыки, разложенный по подпапкам (CD1, CD2), больше не рассыпается в каталоге на безымянные плитки: это одна плитка альбома, а диски идут его частями. «Играть всё» собирает диски по порядку, а любой диск можно включить отдельно — и на экране альбома, и в выборе музыки под фильм, и в слайд-шоу.',
  E'Агент. musicTiles: папка без своих треков, у которой треки есть в подпапках, — одна плитка с Seasons (части) и рекурсивным счётчиком; подпапки отдельными плитками больше не показываются (глубже — прежний обход, «Жанр/Исполнитель/Альбом» не схлопывается). GET /api/tracks?id= — треки папки со всеми вложенными в виде /api/browse; у вложенных в имени относительный путь («CD1/01.m4a»), чтобы в списке было видно диск. extractMusicZip → extractAlbumZip(kind): для photo берёт снимки и ролики, для music — треки; попутно обложки и тексты; target=photo-zip в /api/admin/upload/{id}/finish кладёт альбом в библиотеку вида photo (libraryByKind).\n\nСтраница: раздел «Фото и видео», заголовок альбома «Альбом: …»; экран папки музыки грузит треки через /api/tracks и показывает кнопки дисков (data-mpart); в выборе музыки под фильм и в слайд-шоу у альбома с дисками появились «↳ CD1», «↳ CD2»; в админке две карточки загрузки архивом.\n\nПроверено: TestMusicAlbumWithDiscs (одна плитка, части, рекурсивные треки), TestPhotoZipUpload (альбом с подпапками, мусор отброшен, архив с фото как музыка — понятный отказ), в браузере: диски на экране альбома и в выборе музыки, ZIP с фото через админку (альбом «Поездка» с «День 1» и «День 2»).'
);
-- +goose StatementEnd

